import http from 'k6/http';
import { check, sleep } from 'k6';
export default function () {
  const r = http.get('https://api.example.com/quotes/BTCUSD');
  check(r, { 'status is 200': (res) => res.status === 200 });
}
```

## Follow-up Questions
- How would you validate quota eviction semantics across tenants under shared resources?
- How would you extend tests to cover circuit-breaker behavior and retry backoffs in the face of downstream kafka failures?

## Why This Is Asked
Tests across orchestration layers are common in real systems and subtle with async flows.

## Key Concepts
- End-to-end orchestration
- Idempotency keys
- Eventual consistency
- Distributed tracing
- Failure injection

## Code Example
```javascript
// pseudo-test using jest-like framework
test('end-to-end order orchestration', async () => {
  const key = generateIdempotencyKey();
  const res = await POST('/orders', { itemId, qty, idempotencyKey: key });
  expect(res.status).toBe(202);
  // then poll status until CONFIRMED or timeout
});
```

